/* From Uiverse.io by HoseinParvaresh  - Tags: form, login , login form, dark, rounded, input, button, orange, gradient, minimalistic, password, form, username, centered, login */
.__UIV_SCOPE__ ::selection {
  background-color: gray;
}

.__UIV_SCOPE__ .container {
  margin: 0 auto;
  display: flex;
  justify-content: center;
  align-items: center;
}

.__UIV_SCOPE__ .form {
  width: 400px;
  height: 400px;
  background-image: linear-gradient(to bottom, #424242, #212121);
  display: flex;
  align-items: center;
  flex-direction: column;
  border-radius: 0.5rem;
}

.__UIV_SCOPE__ .title {
  color: wheat;
  margin: 3rem 0;
  font-size: 2rem;
}

.__UIV_SCOPE__ .input {
  margin: 0.5rem 0;
  padding: 1rem 0.5rem;
  width: 20rem;
  background-color: inherit;
  color: wheat;
  border: none;
  outline: none;
  border-bottom: 1px solid wheat;
  transition: all 400ms;
}
.__UIV_SCOPE__ .input:hover {
  background-color: #424242;
  border: none;
  border-radius: 0.5rem;
}
.__UIV_SCOPE__ .btn {
  height: 3rem;
  width: 20rem;
  margin-top: 3rem;
  background-color: wheat;
  border-radius: 0.5rem;
  border: none;
  font-size: 1.2rem;
  transition: all 400ms;
  cursor: pointer;
  box-shadow:
    0 0 10px antiquewhite,
    0 0 10px antiquewhite;
}
.__UIV_SCOPE__ .btn:hover {
  background-color: antiquewhite;
  box-shadow: none;
}
